<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_social_members_query( $search = '', $interest = '', $sort = 'active', $page = 1, $per_page = 12 ) { if ( ! class_exists( 'BP_Core_User' ) ) { return array( 'users' => array(), 'total' => 0 ); } $args = array( 'type' => function_exists( 'sd_core_allowed_member_sort' ) ? sd_core_allowed_member_sort( $sort ) : 'active', 'search_terms' => sanitize_text_field( $search ), 'per_page' => min( 24, max( 1, absint( $per_page ) ) ), 'page' => max( 1, absint( $page ) ) ); $result = BP_Core_User::get( $args ); if ( empty( $result['users'] ) ) { return array( 'users' => array(), 'total' => 0 ); } if ( function_exists( 'sd_core_blocked_ids' ) ) { $blocked = sd_core_blocked_ids(); $result['users'] = array_values( array_filter( $result['users'], function( $user ) use ( $blocked ) { return ! in_array( absint( $user->ID ), $blocked, true ); } ) ); } if ( $interest && function_exists( 'sd_core_user_interests' ) ) { $result['users'] = array_values( array_filter( $result['users'], function( $user ) use ( $interest ) { return in_array( sanitize_text_field( $interest ), sd_core_user_interests( $user->ID ), true ); } ) ); } $result['total'] = count( $result['users'] ); return $result; }
